#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long s, t;
} Act;

int cmp(const void *a, const void *b) {
    const Act *x = (const Act *)a;
    const Act *y = (const Act *)b;
    if (x->t != y->t) return x->t < y->t ? -1 : 1;
    if (x->s != y->s) return x->s < y->s ? -1 : 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Act *a = (Act *)malloc(sizeof(Act) * (size_t)n);
    if (a == NULL) return 0;
    for (int i = 0; i < n; ++i) {
        if (scanf("%lld %lld", &a[i].s, &a[i].t) != 2) {
            free(a);
            return 0;
        }
    }
    qsort(a, (size_t)n, sizeof(Act), cmp);
    int ans = 0;
    long long last = -1; /* 上一个选中活动的结束时刻 */
    for (int i = 0; i < n; ++i) {
        if (a[i].s >= last) {
            ++ans;
            last = a[i].t;
        }
    }
    printf("%d\n", ans);
    free(a);
    return 0;
}

