using namespace std;

struct Item {
    long long w, v;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long W;
    if (!(cin >> n >> W)) return 0;
    vector<Item> items(n);
    for (auto &item : items) cin >> item.w >> item.v;

    sort(items.begin(), items.end(), [](const Item &a, const Item &b) {
        long long left = a.v * b.w;
        long long right = b.v * a.w;
        if (left != right) return left > right; // 单位价值高者优先
        return a.w < b.w;
    });

    long long full = 0, rem = W, num = 0, den = 1;
    bool hasFrac = false;
    for (const auto &item : items) {
        if (rem == 0) break;
        if (item.w <= rem) {
            rem -= item.w;
            full += item.v;
        } else {
            num = item.v * rem;
            den = item.w;
            hasFrac = true;
            rem = 0;
        }
    }

    long long cents = full * 100;
    if (hasFrac) {
        long long scaled = num * 100;
        cents += scaled / den;
        if ((scaled % den) * 2 >= den) ++cents; // 四舍五入到分
    }
    cout << cents / 100 << '.' << setfill('0') << setw(2) << cents % 100 << '\n';
    return 0;
}

#include <stdio.h>

/* 小根堆：维护当前所有果子堆的重量 */
long long heap[10005];
int sz = 0;

void push(long long x) {
    int i = ++sz;
    while (i > 1 && heap[i / 2] > x) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i] = x;
}

long long pop(void) {
    long long ret = heap[1];
    long long x = heap[sz--];
    int i = 1;
    while (i * 2 <= sz) {
        int c = i * 2;
        if (c + 1 <= sz && heap[c + 1] < heap[c]) c++;
        if (heap[c] >= x) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = x;
    return ret;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        scanf("%lld", &x);
        push(x);
    }

    /* 每次合并重量最小的两堆，代价累加 */
    long long ans = 0;
    while (sz > 1) {
        long long a = pop();
        long long b = pop();
        ans += a + b;
        push(a + b);
    }
    printf("%lld\n", ans);
    return 0;
}

