int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    /* 小根堆：维护当前所有果子堆的重量 */
    priority_queue<long long, vector<long long>, greater<long long> > pq;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        pq.push(x);
    }

    /* 每次合并重量最小的两堆，代价累加 */
    long long ans = 0;
    while (pq.size() > 1) {
        long long a = pq.top();
        pq.pop();
        long long b = pq.top();
        pq.pop();
        ans += a + b;
        pq.push(a + b);
    }
    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long l, r;
} Seg;

int cmp(const void *a, const void *b) {
    const Seg *x = (const Seg *)a;
    const Seg *y = (const Seg *)b;
    if (x->l != y->l) return x->l < y->l ? -1 : 1;
    if (x->r != y->r) return x->r < y->r ? -1 : 1;
    return 0;
}

int main(void) {
    long long m;
    int n;
    if (scanf("%lld %d", &m, &n) != 2) return 0;
    Seg *a = (Seg *)malloc(sizeof(Seg) * n);
    for (int i = 0; i < n; ++i) {
        scanf("%lld %lld", &a[i].l, &a[i].r);
    }
    qsort(a, n, sizeof(Seg), cmp);

    /* 已覆盖 1..covered，每步选能接上且右端点最远的区间 */
    long long covered = 0;
    int idx = 0, ans = 0;
    while (covered < m) {
        long long best = covered;
        while (idx < n && a[idx].l <= covered + 1) {
            if (a[idx].r > best) best = a[idx].r;
            ++idx;
        }
        if (best == covered) {
            printf("-1\n");
            free(a);
            return 0;
        }
        covered = best;
        ++ans;
    }
    printf("%d\n", ans);
    free(a);
    return 0;
}

