#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    static int a[100005];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    if (n == 1) { printf("0\n"); return 0; }
    long long jumps = 0;
    int cur_end = 0, farthest = 0, reachable = 1;
    for (int i = 0; i < n - 1; i++) {
        if (i + a[i] > farthest) farthest = i + a[i];
        if (i == cur_end) {
            if (farthest <= i) { reachable = 0; break; }
            jumps++;
            cur_end = farthest;
            if (cur_end >= n - 1) break;
        }
    }
    // 按层贪心：每层扩展当前能到达的最远位置
    if (reachable) printf("%lld\n", jumps);
    else printf("-1\n");
    return 0;
}

