#include <stdio.h>
#include <stdlib.h>

static long long *tmp; /* 归并辅助数组 */
static long long cnt;  /* 逆序对总数 */

/* 归并排序 [l, r)，合并时统计跨越中点的逆序对 */
static void merge_count(long long *a, int l, int r) {
    if (r - l <= 1) return;
    int m = (l + r) / 2;
    merge_count(a, l, m);
    merge_count(a, m, r);
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            cnt += m - i;
            tmp[k++] = a[j++];
        }
    }
    while (i < m) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    for (i = l; i < r; i++) a[i] = tmp[i];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long *a = (long long *)malloc(sizeof(long long) * n);
    tmp = (long long *)malloc(sizeof(long long) * n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    cnt = 0;
    merge_count(a, 0, n);
    printf("%lld\n", cnt);
    free(a);
    free(tmp);
    return 0;
}

#include <iostream>
