long long cnt = 0;

/* 归并排序 [l, r)，合并时统计跨越中点的逆序对 */
void mergeCount(vector<long long> &a, vector<long long> &tmp, int l, int r) {
    if (r - l <= 1) return;
    int m = (l + r) / 2;
    mergeCount(a, tmp, l, m);
    mergeCount(a, tmp, m, r);
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            cnt += m - i;
            tmp[k++] = a[j++];
        }
    }
    while (i < m) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    for (i = l; i < r; i++) a[i] = tmp[i];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n), tmp(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    cnt = 0;
    mergeCount(a, tmp, 0, n);
    cout << cnt << '\n';
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a, b, p;
    scanf("%lld %lld %lld", &a, &b, &p);
    long long ans = 1 % p; /* p 为 1 时答案为 0 */
    a %= p;
    /* 快速幂：按二进制位逐位平方、相乘 */
    while (b > 0) {
        if (b & 1) ans = ans * a % p;
        a = a * a % p;
        b >>= 1;
    }
    printf("%lld\n", ans);
    return 0;
}

