#include <stdlib.h>

int main(void) {
    int n, k;
    scanf("%d %d", &n, &k);
    int *L = (int *)malloc(sizeof(int) * n);
    int maxL = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &L[i]);
        if (L[i] > maxL) maxL = L[i];
    }
    /* 二分答案：答案在 [0, maxL] 中，0 表示无解 */
    int lo = 0, hi = maxL + 1;
