    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 2, 0));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= i; ++j)
            std::cin >> dp[i][j];
    // 自底向上递推，每个位置选两个子结点中的较大值
    for (int i = n - 1; i >= 1; --i)
        for (int j = 1; j <= i; ++j)
            dp[i][j] += std::max(dp[i + 1][j], dp[i + 1][j + 1]);
    std::cout << dp[1][1] << '\n';
    return 0;
}

#include <stdio.h>

#define MAXA 10000
#define INF 1000000000

int dp[MAXA + 1];

int main(void) {
    int n, amount;
    if (scanf("%d %d", &n, &amount) != 2) return 0;
    dp[0] = 0;
    for (int i = 1; i <= amount; ++i) dp[i] = INF;
    // 完全背包：每种硬币可使用任意多次
    for (int i = 0; i < n; ++i) {
        int c;
        scanf("%d", &c);
        for (int j = c; j <= amount; ++j)
            if (dp[j - c] + 1 < dp[j]) dp[j] = dp[j - c] + 1;
    }
    printf("%d\n", dp[amount] == INF ? -1 : dp[amount]);
    return 0;
}

