static void push(int x) {
    int i = ++hsize;
    heap[i] = x;
    while (i > 1) {
        int p = i / 2;
        if (heap[p] <= heap[i]) break;
        int t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
    }
}

static int pop(void) {
    int res = heap[1];
    heap[1] = heap[hsize--];
    int i = 1;
    while (1) {
        int l = i * 2, r = l + 1, s = i;
        if (l <= hsize && heap[l] < heap[s]) s = l;
        if (r <= hsize && heap[r] < heap[s]) s = r;
        if (s == i) break;
        int t = heap[s];
        heap[s] = heap[i];
        heap[i] = t;
        i = s;
    }
    return res;
}

