    int cnt = 0;
    static int order[100005];
    // Kahn 算法配合小根堆，每一步取当前可选的最小结点
    while (hsize > 0) {
        int u = pop();
        order[cnt++] = u;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            indeg[v]--;
            if (indeg[v] == 0) push(v);
        }
    }

    if (cnt < n) {
        puts("-1");
    } else {
        for (int i = 0; i < cnt; i++) {
            if (i > 0) putchar(' ');
            printf("%d", order[i]);
        }
        putchar('\n');
    }
    return 0;
}

