#define MAXN 100005

static int parent[MAXN], rnk[MAXN];

/* 查找根结点，带路径压缩 */
int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        rnk[i] = 0;
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        /* 按秩合并 */
        int ru = find(u), rv = find(v);
        if (ru != rv) {
            if (rnk[ru] < rnk[rv]) {
                int t = ru;
                ru = rv;
                rv = t;
            }
            parent[rv] = ru;
            if (rnk[ru] == rnk[rv]) rnk[ru]++;
        }
    }
    int q;
    scanf("%d", &q);
    while (q--) {
        int a, b;
        scanf("%d %d", &a, &b);
        puts(find(a) == find(b) ? "Yes" : "No");
    }
    return 0;
}

