using namespace std;

struct DSU {
    vector<int> fa, sz;
    explicit DSU(int n) : fa(n + 1), sz(n + 1, 1) {
        for (int i = 1; i <= n; i++) fa[i] = i;
    }
    // 路径压缩查找
    int find(int x) {
        while (fa[x] != x) {
            fa[x] = fa[fa[x]];
            x = fa[x];
        }
        return x;
    }
    // 按大小合并
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        fa[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    DSU dsu(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }
    int q;
    cin >> q;
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << (dsu.find(a) == dsu.find(b) ? "Yes" : "No") << "\n";
    }
    return 0;
}

#include <stdio.h>

#define MAXN 100005
#define LOG 17

static int head[MAXN], to[2 * MAXN], nxt[2 * MAXN];
static int depth[MAXN], up[LOG][MAXN], que[MAXN];

int main(void) {
    int n, root;
    if (scanf("%d %d", &n, &root) != 2) return 0;
    for (int i = 1; i <= n; i++) head[i] = -1;
    int ecnt = 0;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;
        to[ecnt] = u; nxt[ecnt] = head[v]; head[v] = ecnt++;
    }

    for (int i = 0; i <= n; i++) {
        depth[i] = 0;
        up[0][i] = 0;
    }
    /* BFS 求深度与一级祖先 */
    int front = 0, back = 0;
    que[back++] = root;
    up[0][root] = root;
    while (front < back) {
        int u = que[front++];
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == up[0][u]) continue;
            up[0][v] = u;
            depth[v] = depth[u] + 1;
            que[back++] = v;
        }
    }
    /* up[k][v] 为 v 向上走 2^k 步到达的祖先 */
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++)
            up[k][v] = up[k - 1][up[k - 1][v]];

    int q;
    scanf("%d", &q);
    while (q--) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (depth[u] < depth[v]) {
            int t = u;
            u = v;
            v = t;
        }
        /* 先对齐深度，再同时上跳 */
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++)
            if ((diff >> k) & 1) u = up[k][u];
        if (u != v) {
            for (int k = LOG - 1; k >= 0; k--)
                if (up[k][u] != up[k][v]) {
                    u = up[k][u];
                    v = up[k][v];
                }
            u = up[0][u];
        }
        printf("%d\n", u);
    }
    return 0;
}

