    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, root;
    if (!(cin >> n >> root)) return 0;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    // 倍增预处理：up[k][v] 是 v 的 2^k 级祖先
    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
    vector<int> depth(n + 1, 0), stk;
    stk.push_back(root);
    up[0][root] = root;
    while (!stk.empty()) {
        int u = stk.back();
        stk.pop_back();
        for (int v : adj[u]) {
            if (v == up[0][u]) continue;
            up[0][v] = u;
            depth[v] = depth[u] + 1;
            stk.push_back(v);
        }
    }
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++)
            up[k][v] = up[k - 1][up[k - 1][v]];

    int q;
    cin >> q;
    while (q--) {
        int u, v;
        cin >> u >> v;
        if (depth[u] < depth[v]) swap(u, v);
        // 先把较深结点提到同一深度
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++)
            if ((diff >> k) & 1) u = up[k][u];
        if (u != v) {
            // 一起上跳，直到两者的祖先相同
            for (int k = LOG - 1; k >= 0; k--)
                if (up[k][u] != up[k][v]) {
                    u = up[k][u];
                    v = up[k][v];
                }
            u = up[0][u];
        }
        cout << u << "\n";
    }
    return 0;
}

#include <stdio.h>
/* dfn：DFS 时间戳；low：能回溯到的最小时间戳 */

#define MAXN 10005
#define MAXM 50005

int head[MAXN], nxt[MAXM], to[MAXM], ecnt;
int dfn[MAXN], low[MAXN], inStack[MAXN], stk[MAXN];
int timer, top, sccCnt;

void addEdge(int u, int v) {
    to[++ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

void tarjan(int u) {
    dfn[u] = low[u] = ++timer;
    stk[++top] = u;
    inStack[u] = 1;
    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        if (!dfn[v]) {
            tarjan(v);
            if (low[v] < low[u]) low[u] = low[v];
        } else if (inStack[v] && dfn[v] < low[u]) {
            low[u] = dfn[v];
        }
    }
    if (low[u] == dfn[u]) {
        ++sccCnt;
        int w;
        do {
            w = stk[top--];
            inStack[w] = 0;
        } while (w != u);
    }
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        addEdge(u, v);
    }
    for (int i = 1; i <= n; ++i) {
        if (!dfn[i]) tarjan(i);
    }
    printf("%d\n", sccCnt);
    return 0;
}

