using namespace std;

int n, m, timerCnt, sccCnt;
vector<vector<int>> g;
vector<int> dfn, low, stk;
vector<char> inStk;

// Tarjan 求强连通分量
void tarjan(int u) {
    dfn[u] = low[u] = ++timerCnt;
    stk.push_back(u);
    inStk[u] = 1;
    for (int v : g[u]) {
        if (!dfn[v]) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (inStk[v]) {
            low[u] = min(low[u], dfn[v]);
        }
    }
    if (low[u] == dfn[u]) {
        ++sccCnt;
        while (true) {
            int w = stk.back();
            stk.pop_back();
            inStk[w] = 0;
            if (w == u) break;
        }
    }
}

