def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n + 1)]
    pos = 2
    for _ in range(m):
        u, v = data[pos], data[pos + 1]
        pos += 2
        adj[u].append(v)

    dfn = [0] * (n + 1)
    low = [0] * (n + 1)
    on_stack = [False] * (n + 1)
    timer = 0
    scc_cnt = 0

    # 迭代版 Tarjan，栈中保存（结点，下一条待处理边的下标）
    for start in range(1, n + 1):
        if dfn[start]:
            continue
        dfs_stack = [(start, 0)]
        path = []
        while dfs_stack:
            u, edge_idx = dfs_stack.pop()
            if edge_idx == 0:
                timer += 1
                dfn[u] = low[u] = timer
                on_stack[u] = True
                path.append(u)

            if edge_idx < len(adj[u]):
                v = adj[u][edge_idx]
                dfs_stack.append((u, edge_idx + 1))
                if dfn[v] == 0:
                    dfs_stack.append((v, 0))
                elif on_stack[v] and dfn[v] < low[u]:
                    low[u] = dfn[v]
            else:
                if dfs_stack:
                    parent = dfs_stack[-1][0]
                    if low[u] < low[parent]:
                        low[parent] = low[u]
                # 找到一个新的强连通分量
                if low[u] == dfn[u]:
                    scc_cnt += 1
                    while True:
                        w = path.pop()
                        on_stack[w] = False
                        if w == u:
                            break

    sys.stdout.write(str(scc_cnt) + "\n")


