            int b = (r / 3) * 3 + c / 3;
            int m = FULL & ~(rowMask[r] | colMask[c] | boxMask[b]);
            int cnt = count_bits(m);
            if (cnt == 0) return 0;
            if (cnt < bestCnt) {
                bestCnt = cnt;
                bestR = r;
                bestC = c;
                bestMask = m;
            }
        }
    }
    if (bestR == -1) return 1;

    int b = (bestR / 3) * 3 + bestC / 3;
    for (int d = 1; d <= 9; d++) {
        int bit = 1 << (d - 1);
        if (!(bestMask & bit)) continue;
        board[bestR][bestC] = (char)('0' + d);
        rowMask[bestR] |= bit;
        colMask[bestC] |= bit;
        boxMask[b] |= bit;
        if (dfs()) return 1;
        board[bestR][bestC] = '0';
        rowMask[bestR] &= ~bit;
        colMask[bestC] &= ~bit;
        boxMask[b] &= ~bit;
    }
    return 0;
}

int main(void) {
    for (int r = 0; r < 9; r++) {
        if (scanf("%9s", board[r]) != 1) return 0;
        for (int c = 0; c < 9; c++) {
            if (board[r][c] < '1' || board[r][c] > '9') continue;
            int bit = 1 << (board[r][c] - '1');
            int b = (r / 3) * 3 + c / 3;
            rowMask[r] |= bit;
            colMask[c] |= bit;
            boxMask[b] |= bit;
        }
    }
    dfs();
    for (int r = 0; r < 9; r++) printf("%s\n", board[r]);
    return 0;
}

