string board[9];
int rowMask[9], colMask[9], boxMask[9];
const int FULL = (1 << 9) - 1;

int countBits(int x) {
    int cnt = 0;
    while (x) {
        cnt += x & 1;
        x >>= 1;
    }
    return cnt;
}

// MRV 剪枝：每次填候选数最少的空格
bool dfs() {
    int bestR = -1, bestC = -1, bestMask = 0, bestCnt = 10;
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (board[r][c] != '0') continue;
            int b = (r / 3) * 3 + c / 3;
            int m = FULL & ~(rowMask[r] | colMask[c] | boxMask[b]);
            int cnt = countBits(m);
            if (cnt == 0) return false;
            if (cnt < bestCnt) {
                bestCnt = cnt;
                bestR = r;
                bestC = c;
                bestMask = m;
            }
        }
    }
    if (bestR == -1) return true;

    int b = (bestR / 3) * 3 + bestC / 3;
    for (int d = 1; d <= 9; ++d) {
        int bit = 1 << (d - 1);
        if (!(bestMask & bit)) continue;
        board[bestR][bestC] = char('0' + d);
        rowMask[bestR] |= bit;
        colMask[bestC] |= bit;
        boxMask[b] |= bit;
        if (dfs()) return true;
        board[bestR][bestC] = '0';
        rowMask[bestR] &= ~bit;
        colMask[bestC] &= ~bit;
        boxMask[b] &= ~bit;
    }
    return false;
}

