        }
        while (i - r - 1 >= 0 && i + r + 1 < m && t[i - r - 1] == t[i + r + 1]) r++;
        rad[i] = r;
        if (i + r > right) {
            center = i;
            right = i + r;
        }
        if (r > bestLen) {
            bestLen = r;
            bestStart = (i - r) / 2;
        }
    }

    printf("%d\n", bestLen);
    for (int k = 0; k < bestLen; k++) putchar(s[bestStart + k]);
