        for (int j = left; j <= right; j++) {
            if (!first) putchar(' ');
            printf("%d", a[top][j]);
            first = 0;
        }
        top++;
        for (int i = top; i <= bottom; i++) {
            if (!first) putchar(' ');
            printf("%d", a[i][right]);
            first = 0;
        }
        right--;
        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                if (!first) putchar(' ');
                printf("%d", a[bottom][j]);
                first = 0;
            }
            bottom--;
        }
        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                if (!first) putchar(' ');
                printf("%d", a[i][left]);
                first = 0;
            }
            left++;
        }
    }
    putchar('\n');
    return 0;
}

