#include <stdio.h>

#define CAP (1 << 20)

static long long hkey[CAP];
static long long hcnt[CAP];
static unsigned char hused[CAP];

static unsigned long long mix(unsigned long long x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

// 开放寻址哈希表：找到键 k 对应的槽位，不存在则插入空槽
static int slot(long long k) {
    int h = (int)(mix((unsigned long long)k) & (CAP - 1));
    while (hused[h] && hkey[h] != k)
        h = (h + 1) & (CAP - 1);
    if (!hused[h]) {
        hused[h] = 1;
        hkey[h] = k;
        hcnt[h] = 0;
    }
    return h;
}

int main(void) {
    int n;
    long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;

    int s = slot(0);
    hcnt[s] = 1;
    long long prefix = 0, ans = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        prefix += x;
        s = slot(prefix - k);
        ans += hcnt[s];
        s = slot(prefix);
        hcnt[s]++;
    }
    printf("%lld\n", ans);
    return 0;
}

#include <iostream>
#include <unordered_map>
using namespace std;

// 自定义哈希函数，降低被固定哈希值影响而退化的可能
struct SplitMix {
    size_t operator()(long long x) const {
        unsigned long long z = (unsigned long long)x + 0x9e3779b97f4a7c15ULL;
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        return (size_t)(z ^ (z >> 31));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    unordered_map<long long, long long, SplitMix> cnt;
    cnt.max_load_factor(0.7f);
    cnt.reserve(n + 10);
    cnt[0] = 1;

    long long prefix = 0, ans = 0;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        prefix += x;
        auto it = cnt.find(prefix - k);
        if (it != cnt.end()) ans += it->second;
        cnt[prefix]++;
    }
    cout << ans << '\n';
    return 0;
}

#include <stdio.h>

static long long d[200005];

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    // 区间 [l, r] 加 v：差分数组 d[l] += v, d[r+1] -= v
    for (int i = 0; i < m; i++) {
        int l, r;
        long long v;
        scanf("%d %d %lld", &l, &r, &v);
        d[l] += v;
        d[r + 1] -= v;
    }

    long long cur = 0;
    for (int i = 1; i <= n; i++) {
        cur += d[i];
        if (i > 1) putchar(' ');
        printf("%lld", cur);
    }
    putchar('\n');
    return 0;
}

